 const left=act(s,{...card,path:['B2']}),right=act(s,{...card,path:[]});const leftView=projection(left,1),rightView=projection(right,1);assert.deepEqual({...leftView,turnId:"same-transition"},{...rightView,turnId:"same-transition"});assert.equal(projection(left,1).killerLocation,null);assert.equal(left.killerLocation,'B2');assert.deepEqual(left.blocks,['B1-B2']);
 s=act(left,{type:'KILLER_NEXT'});s.survivors[0]!.location='B1';s=teamAct(s,basic('ANNA','REPAIR'));assert.equal(s.repair,1);
