 s=act(s,{type:'ATTACK_CARD',cardId:null});s=teamAct(s,{type:'DEFENDER',character:'WILLIAM'},'WILLIAM');s=teamAct(s,{type:'DEFEND',cardId:null},'WILLIAM');assert.equal(s.phase,'FLEE');rejected(s,{type:'KILLER_NEXT'});
