function grantTrait(s:TerrorscapeState,t:TerrorTrait,c:TerrorCharacter|null=null){if(c){s.survivorTraits.find(p=>p.character===c)!.chosen=t;}else s.killerTraits.push(t);}
function traitAction(trait:TerrorTrait,character:TerrorCharacter|null=null,options:Partial<Extract<TerrorscapeAction,{type:'TRAIT_USE'}>>={}):Extract<TerrorscapeAction,{type:'TRAIT_USE'}>{return {type:'TRAIT_USE',trait,character,target:'ANNA',path:[],room:'R1',zone:'R',choice:'FEAR',cost:[],edges:[],replaces:[],...options};}
function completePlan(s:TerrorscapeState,plan:TerrorPlan){s.plansEnabled=true;s.plan={cards:[plan],active:plan,progress:TERROR_PLAN_INFO[plan].steps.length,complete:true,used:false,location:null,chooser:'ANNA'};}
function planAction(character:TerrorCharacter='ANNA',options:Partial<Extract<TerrorscapeAction,{type:'PLAN_USE'}>>={}):Extract<TerrorscapeAction,{type:'PLAN_USE'}>{return {type:'PLAN_USE',character,target:character,path:[],destination:'R1',cards:[],...options};}
test('Terrorscape variants: all 16 plans progress one step at a time, remain private and lock alternatives',()=>{
 for(const plan of TERROR_PLANS){let s=begun();s.plansEnabled=true;s.plan.cards=[plan];s.plan.chooser='ANNA';for(const step of TERROR_PLAN_INFO[plan].steps){s.phase='PLAN';for(const p of s.survivors)p.location='R1';if(step==='APART'){s.survivors[1]!.location='R2';s.survivors[2]!.location='R3';}else if(step!=='TOGETHER')s.survivors[0]!.location=step==='KILLER'?s.killerLocation:step==='BOOK'?'R5':step==='TOOLS'?'G3':step==='OCCULT'?'G2':step==='RADIO'?'B1':'G5';const before=s.plan.progress;s=teamAct(s,{type:'PLAN_PROGRESS',plan,target:'ANNA'});assert.equal(s.plan.progress,before+1,plan);if(s.phase==='LOOT')s=teamAct(s,{type:'KEEP',cardId:null});assert.equal(JSON.stringify(projection(s,0)).includes(plan),false,plan);}assert.equal(s.plan.complete,true,plan);parseTerrorscapeState(s);}
 let s=begun();s.plansEnabled=true;s.plan.cards=['BLUEPRINT','MYSTIC_HERBS'];s.plan.chooser='ANNA';s.phase='PLAN';s.survivors[0]!.location='R5';s=teamAct(s,{type:'PLAN_PROGRESS',plan:'BLUEPRINT',target:'ANNA'});s.phase='PLAN';rejected(s,{type:'PLAN_PROGRESS',plan:'MYSTIC_HERBS',target:'ANNA'},s.survivors[0]!.playerId);s.survivors[0]!.location='G2';s=teamAct(s,{type:'PLAN_PROGRESS',plan:'MYSTIC_HERBS',target:'ANNA'});assert.equal(s.plan.active,'MYSTIC_HERBS');assert.equal(s.plan.progress,1);
});
