test('Terrorscape traits: Martial Arts, luck, secret weapon, ammo bonus and improved flee',()=>{
 for(const t of ['MARTIAL','LUCK','SECRET_WEAPON','MARKSMAN','SURVIVAL_INSTINCT'] as const){let s=begun();grantTrait(s,t,'ANNA');s.phase='MAIN';s.killerLocation='R1';if(t==='MARKSMAN'){give(s,'ANNA','REVOLVER');give(s,'ANNA','AMMO');}s=act(s,{type:'KILLER_BASIC',kind:'SEARCH',destination:'R1'});s=teamAct(s,{type:'DEFENDER',character:'ANNA'});if(t==='SECRET_WEAPON')s=teamAct(s,traitAction(t,'ANNA'), 'ANNA',{nextInt:()=>0});else s=teamAct(s,{type:'DEFEND',cardId:t==='MARKSMAN'?s.survivors[0]!.hand.find(c=>c.key==='AMMO')!.cardId:null},'ANNA',t==='SURVIVAL_INSTINCT'?{nextInt:()=>5}:{nextInt:()=>0});if(t==='MARTIAL')assert.equal(s.defenseTotal,1);if(t==='LUCK')assert.equal(s.phase,'FLEE');if(t==='SECRET_WEAPON'){assert.equal(s.defenseTotal,4);assert.ok(s.usedTraits.includes(t));}if(t==='MARKSMAN'){assert.equal(s.defenseTotal,5);assert.equal(s.phase,'FLEE');}if(t==='SURVIVAL_INSTINCT'){s.survivors[0]!.fear=2;s=teamAct(s,{type:'FLEE',character:'ANNA',destination:'R5',path:['R2','R5']});assert.equal(s.survivors[0]!.fear,0);assert.equal(s.survivors[0]!.location,'R5');}}
});
test('Terrorscape traits: survivor active effects enforce costs, turn consumption and once-only use',()=>{
 for(const t of ['FIRST_AID','MORALE','DECOY','JUDICIOUS','PROMPT','BURST'] as const){let s=begun();grantTrait(s,t,'ANNA');s.survivors[1]!.injuries=1;s.survivors[1]!.fear=2;s.survivors[0]!.fear=2;const a=traitAction(t,'ANNA',{target:'WILLIAM',room:'G5',path:t==='PROMPT'?['R2']:t==='BURST'?['R2','R5']:[]});s=teamAct(s,a);if(t==='FIRST_AID')assert.equal(s.survivors[1]!.injuries,0);if(t==='MORALE')assert.equal(s.survivors[1]!.fear,1);if(t==='DECOY')assert.ok(s.pendingNoises.includes('G5'));if(t==='JUDICIOUS')assert.equal(s.survivors[0]!.fear,0);if(t==='PROMPT')assert.equal(s.survivors[0]!.location,'R2');if(t==='BURST'){assert.equal(s.survivors[0]!.location,'R5');assert.ok(s.pendingNoises.includes('R1'));}assert.equal(s.survivors[0]!.acted,['FIRST_AID','MORALE','BURST'].includes(t));if(TERROR_TRAIT_INFO[t].once)rejected(s,a,s.survivors[0]!.playerId);}
 let s=begun();grantTrait(s,'TAUNT','ANNA');const before=s.killerDeck.length;s=teamAct(s,traitAction('TAUNT','ANNA'));assert.equal(s.round,1);assert.equal(s.killerDeck.length,before-4);assert.equal(s.hand.length,3);assert.equal(s.phase,'SURVIVORS');
});
